import {createMediaRepository} from './repository.mjs';import {validateAsset,validateMediaUsage} from '../../authoring/media.mjs';
export async function bootMedia({document=globalThis.document,repo=createMediaRepository()}={}){
 const doc=document,form=doc.querySelector('#media-form'),status=doc.querySelector('#media-status'),field=name=>form.elements.namedItem(name);let assets=[],articles=[],usage=[],busy=false;
 const el=(tag,text)=>{const n=doc.createElement(tag);if(text!==undefined)n.textContent=text;return n;},setStatus=text=>status.textContent=text,current=()=>usage.find(u=>u.article_id===field('article_id').value&&u.asset_id===field('asset_id').value&&u.block_ref===field('block_ref').value);
 function loadReference(){const u=current();field('alt_text').value=u?.alt_text||'';field('caption').value=u?.caption||'';field('decorative').checked=u?.decorative||false;decorative();doc.querySelector('#media-version').textContent=u?'Saved private reference · version '+u.edit_version:'New private reference';}
 function decorative(){const value=field('decorative').checked;field('alt_text').disabled=value;field('alt_text').required=!value;if(value)field('alt_text').value='';}
 function renderUsage(){const mount=doc.querySelector('#media-usage');mount.replaceChildren();for(const u of usage){const row=el('article');row.dataset.mediaUsage='';const title=articles.find(a=>a.id===u.article_id)?.draft.title||'Article',asset=assets.find(a=>a.id===u.asset_id);row.append(el('h3',title+' / '+asset.filename),el('p',(u.decorative?'Decorative image':u.alt_text)+(u.caption?' — '+u.caption:'')));const button=el('button','Edit private reference');button.type='button';button.addEventListener('click',()=>{field('article_id').value=u.article_id;field('asset_id').value=u.asset_id;field('block_ref').value=u.block_ref;loadReference();form.scrollIntoView({block:'nearest'});});row.append(button);mount.append(row);}if(!usage.length)mount.append(el('p','No article references saved.'));}
 async function reload(){[assets,articles,usage]=await Promise.all([repo.assets(),repo.articles(),repo.usage()]);assets.forEach(validateAsset);const mount=doc.querySelector('#media-assets');mount.replaceChildren();if(!assets.length)mount.append(el('p','No approved media assets are available.'));for(const a of assets){const row=el('article');row.dataset.mediaAsset='';const img=el('img');img.src=a.path;img.alt='';img.width=a.width;img.height=a.height;const metadata=el('div'),identity=el('details');metadata.className='admin-media-metadata';identity.append(el('summary','Technical identity'),el('small','SHA-256 '+a.sha256));metadata.append(el('h3',a.filename),el('p',`${a.mime_type} · ${a.width} × ${a.height} · ${a.byte_size} bytes`),identity);row.append(img,metadata);mount.append(row);}for(const [name,rows,label] of [['article_id',articles,a=>a.draft.title],['asset_id',assets,a=>a.filename]]){field(name).replaceChildren();for(const a of rows){const option=el('option',label(a));option.value=a.id;field(name).append(option);}}doc.querySelector('#media-save').disabled=!assets.length||!articles.length;loadReference();renderUsage();}
 for(const name of ['article_id','asset_id','block_ref'])field(name).addEventListener('change',loadReference);field('decorative').addEventListener('change',decorative);
 form.addEventListener('submit',async event=>{event.preventDefault();if(busy)return;busy=true;const button=doc.querySelector('#media-save');button.disabled=true;try{const u=validateMediaUsage({article_id:field('article_id').value,asset_id:field('asset_id').value,block_ref:field('block_ref').value,alt_text:field('alt_text').value,caption:field('caption').value,decorative:field('decorative').checked}),saved=await repo.save(u,current()?.edit_version||0);usage=usage.filter(a=>!(a.article_id===saved.article_id&&a.asset_id===saved.asset_id&&a.block_ref===saved.block_ref));usage.unshift(saved);loadReference();renderUsage();setStatus('Saved private metadata. Public articles and published revisions are unchanged.');}catch(e){setStatus(e.message);}finally{busy=false;button.disabled=false;}});
 setStatus('Loading approved media and article references…');
 try{await reload();setStatus('Approved media registry loaded.');}catch(e){form.hidden=true;setStatus(e.message);}return {reload};
}
if(typeof document!=='undefined'&&document.querySelector('[data-hub-media]'))bootMedia();
